#include <vector>
#include <iostream>

int main() {
    std::vector<int> v = {1, 2, 3};

    int& ref_to_2 = v[1]; // Reference to element 2
    auto it = v.begin();  // Iterator to element 1

    // Inserting at the beginning invalidates all.
    v.insert(v.begin(), 0);

    // std::cout << *it; // DANGER: UB, it is potentially invalid
    // std::cout << ref_to_2; // DANGER: UB, ref_to_2 is potentially invalid

    // Correct usage: update the iterator
    std::vector<int> v2 = {1, 2};
    auto new_it = v2.insert(v2.begin() + 1, 99);
    std::cout << "New element: " << *new_it << std::endl;
}
